package dev.zomboid.mts;
import java.util.*;
public final class VehiclePicker {
 static String p="minecrafttransportsimulator.";
 public static boolean useful(Object entity,Object box){Object definition=R.get(box,"definition");if(definition!=null&&R.get(definition,"action")!=null)return true;String type=entity.getClass().getSimpleName();return type.equals("PartSeat")||type.equals("PartEngine")||type.equals("PartInteractable");}
 public static Object choose(Object world,Object eye,Object start,Object end,Object nativeHit){if(nativeHit!=null&&useful(R.get(nativeHit,"entity"),R.get(nativeHit,"box")))return nativeHit;Object best=null;double bestDistance=Double.POSITIVE_INFINITY;for(Object vehicle:(Collection<?>)R.call(world,"getEntitiesOfType",R.type(p+"entities.instances.EntityVehicleF_Physics"))){if(!R.yes(R.call(vehicle,"canBeClicked")))continue;for(Object box:(Collection<?>)R.get(vehicle,"allCollisionBoxes")){Collection<?> types=(Collection<?>)R.get(box,"collisionTypes");if(types.stream().noneMatch(t->t.toString().equals("CLICK")))continue;Object hit=R.call(box,"getIntersection",start,end);if(hit==null)continue;Object position=R.get(hit,"position");if(!VehicleInteraction.reachable(VehicleInteraction.distance(eye,position)))continue;Object part=R.call(vehicle,"getPartWithBox",box),entity=part==null?vehicle:part;if(!R.yes(R.call(entity,"canBeClicked"))||!useful(entity,box))continue;double distance=VehicleInteraction.distance(start,position);if(distance<bestDistance){bestDistance=distance;best=R.make(p+"baseclasses.EntityInteractResult",entity,box,position);}}}return best==null?nativeHit:best;}
}
